/* KHBD Tin học Lớp 3 KNTT — soạn cho Bút Xanh, tích hợp Năng lực số + AI */
window.KHO_DATA_L3_TINHOC = [{"lop":3,"mon":"Tin học","tuan":1,"tiet":1,"bai":"Bài 1: Thông tin và quyết định (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nêu được ví dụ đơn giản minh hoạ vai trò của thông tin thu nhận hằng ngày đối với việc đưa ra quyết định của con người.\n- Nhận biết được thông tin và quyết định trong ví dụ cụ thể.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nêu tình huống: khi nghe tiếng chuông đồng hồ báo thức buổi sáng, bạn Minh sẽ quyết định làm gì?\n- Cho HS thảo luận, báo cáo; GV nhận xét, dẫn vào bài.","hs":"- HS thảo luận, trả lời: nghe chuông → thức dậy, vệ sinh cá nhân, ăn sáng, đi học.\n- Lắng nghe, nhận ra tiếng chuông là thông tin giúp Minh quyết định."},{"ten":"2. Khám phá: Thông tin và quyết định","gv":"- GV tổ chức nhóm tìm hiểu tình huống trong SGK: điều bạn nhận biết là thông tin, việc bạn chọn làm là quyết định.\n- Chốt: thông tin giúp con người đưa ra quyết định.","hs":"- HS thảo luận, phân biệt câu nào là thông tin, câu nào là quyết định (VD SGK tr.6).\n- Ghi nhớ nội dung hộp kiến thức."},{"ten":"3. Khám phá: Vai trò của thông tin","gv":"- GV nêu ví dụ: biết hôm nay có tiết Giáo dục thể chất → quyết định mang giày thể thao.\n- Cho HS nêu thêm ví dụ; chốt vai trò của thông tin.","hs":"- HS nêu ví dụ của bản thân: có thông tin gì → đưa ra quyết định gì.\n- Trình bày, nhận xét nhóm bạn."},{"ten":"4. Luyện tập","gv":"- GV cho HS làm bài tập phân biệt thông tin/quyết định (SGK tr.8).","hs":"- HS làm bài, chữa bài, giải thích lựa chọn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS quan sát GV dùng máy tính/đồng hồ thông minh minh hoạ cách thiết bị số cung cấp thông tin (giờ, lời nhắc) giúp con người ra quyết định trong đời sống.\n- (Làm quen AI - mức nhận biết) GV cho HS xem trợ lí ảo (loa/điện thoại thông minh) đọc dự báo thời tiết; hỏi: dựa vào thông tin đó em quyết định mặc gì, mang gì khi đi học?\n⚠ GV thao tác và kiểm soát hoàn toàn; HS quan sát, không tự nhập thông tin cá nhân; dùng công cụ số trung thực, an toàn.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":2,"tiet":2,"bai":"Bài 1: Thông tin và quyết định (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nhận biết được ba dạng thông tin thường gặp: chữ, hình ảnh, âm thanh.\n- Vận dụng phân loại được dạng thông tin trong tình huống quen thuộc.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS kể những gì nhìn thấy, nghe thấy trên đường đến trường.","hs":"- HS kể: biển tên trường (chữ), tranh cổ động (hình ảnh), tiếng chim hót (âm thanh)."},{"ten":"2. Khám phá: Ba dạng thông tin","gv":"- GV tổ chức nhóm nhận biết ba dạng thông tin qua hình SGK.\n- Chốt: thông tin thường gặp ở dạng chữ, hình ảnh, âm thanh.","hs":"- HS thảo luận, phân loại thông tin theo ba dạng; ghi nhớ hộp kiến thức."},{"ten":"3. Luyện tập","gv":"- GV cho HS làm bài tập nhận dạng thông tin trên thùng rác phân loại, biển báo... (SGK).","hs":"- HS làm bài, xác định dạng thông tin (chữ/hình ảnh/âm thanh)."},{"ten":"4. Vận dụng","gv":"- GV giao: hãy mô tả một việc em định làm sau khi tan học và cho biết thông tin nào giúp em quyết định.","hs":"- HS thực hiện ngoài giờ, chia sẻ ở tiết sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS xem hình ảnh, video, âm thanh số trên máy tính do GV chuẩn bị và nhận ra đó là ba dạng thông tin (chữ, hình ảnh, âm thanh) được máy tính lưu trữ, trình bày.\n- (Làm quen AI - mức nhận biết) GV giới thiệu: máy tính, điện thoại có thể chuyển lời nói (âm thanh) thành chữ, đọc chữ thành tiếng — đó là bước đầu của công cụ thông minh giúp con người.\n⚠ GV thao tác và kiểm soát hoàn toàn; HS quan sát, không tự nhập thông tin cá nhân; dùng công cụ số trung thực, an toàn.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":3,"tiet":3,"bai":"Bài 2: Xử lí thông tin (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nhận biết được quá trình thu nhận và xử lí thông tin.\n- Nêu được ví dụ minh hoạ bộ não con người là bộ phận xử lí thông tin.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nêu: hình dung một người hát theo video; tai, mắt, bộ não làm nhiệm vụ gì?","hs":"- HS thảo luận: tai nghe, mắt nhìn (thu nhận thông tin), bộ não xử lí để hát theo."},{"ten":"2. Khám phá: Con người xử lí thông tin","gv":"- GV cho HS quan sát hình SGK, tìm hiểu bộ não xử lí thông tin.\n- Chốt: bộ não là nơi xử lí thông tin, tạo quyết định, điều khiển hành động.","hs":"- HS thảo luận, trả lời: bộ phận xử lí thông tin của con người là bộ não; ghi nhớ hộp kiến thức."},{"ten":"3. Luyện tập","gv":"- GV cho HS làm bài tập: xác định bộ phận xử lí thông tin; ví dụ người thả diều thu nhận – xử lí gì.","hs":"- HS làm bài, giải thích."},{"ten":"4. Vận dụng","gv":"- GV giao: nêu một việc hằng ngày của em, cho biết thông tin thu nhận và kết quả xử lí.","hs":"- HS thực hiện, chia sẻ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS quan sát sơ đồ số Thu nhận → Xử lí → Kết quả trên máy chiếu; hiểu quá trình xử lí thông tin của con người một cách trực quan.\n- (Làm quen AI - mức nhận biết) GV nêu: máy tính cũng thu nhận và xử lí thông tin giống bộ não giúp con người; một số công cụ thông minh có thể trả lời câu hỏi khi ta hỏi.\n⚠ GV thao tác và kiểm soát hoàn toàn; HS quan sát, không tự nhập thông tin cá nhân; dùng công cụ số trung thực, an toàn.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":4,"tiet":4,"bai":"Bài 2: Xử lí thông tin (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nêu được ví dụ cho thấy máy móc cũng tiếp nhận thông tin và quyết định hành động.\n- Nhận biết được máy móc xử lí thông tin gì và kết quả ra sao.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS kể tên thiết bị điện trong gia đình điều khiển được (ti vi, máy giặt, điều hoà...).","hs":"- HS kể tên thiết bị và nêu cách điều khiển bằng nút bấm, điều khiển từ xa."},{"ten":"2. Khám phá: Máy xử lí thông tin","gv":"- GV tổ chức nhóm tìm hiểu: con người cung cấp thông tin cho thiết bị, thiết bị xử lí và thực hiện.\n- Chốt: nhiều thiết bị tiếp nhận thông tin để quyết định hành động.","hs":"- HS thảo luận: ví dụ nhấn nút + của bếp từ → bếp nhận thông tin tăng nhiệt → thực hiện; ghi nhớ."},{"ten":"3. Luyện tập","gv":"- GV cho HS ghép cặp thông tin – hành động của máy; giải thích ví dụ bếp từ (SGK).","hs":"- HS làm bài, trình bày."},{"ten":"4. Vận dụng","gv":"- GV: hãy nêu một thiết bị ở nhà em nhận thông tin để hành động và mô tả cách hoạt động.","hs":"- HS thực hiện, chia sẻ tiết sau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS quan sát video/hình ảnh số về các thiết bị thông minh (máy giặt, điều hoà, robot hút bụi) nhận lệnh và tự thực hiện công việc.\n- (Làm quen AI - mức nhận biết) GV giới thiệu trợ lí ảo: khi ra lệnh bằng lời nói, thiết bị nhận thông tin, xử lí và thực hiện — đây là ví dụ máy móc xử lí thông tin giúp con người.\n⚠ GV thao tác và kiểm soát hoàn toàn; HS quan sát, không tự nhập thông tin cá nhân; dùng công cụ số trung thực, an toàn.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":5,"tiet":5,"bai":"Bài 3: Máy tính và em (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nhận diện, phân biệt được hình dạng thường gặp của máy tính thông dụng và các bộ phận cơ bản: màn hình, thân máy, bàn phím, chuột.\n- Nêu được sơ lược chức năng của các bộ phận đó.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV tổ chức trò chơi Ai nhanh – Ai đúng: kể tên các bộ phận của máy tính để bàn.","hs":"- HS tham gia, nêu được 4 bộ phận chính: thân máy, màn hình, bàn phím, chuột."},{"ten":"2. Khám phá: Các bộ phận cơ bản","gv":"- GV cho HS quan sát máy tính thật/hình, chỉ và gọi tên bộ phận; gắn thẻ tên.\n- Chốt chức năng: thân máy (xử lí), màn hình (hiển thị), bàn phím (nhập), chuột (điều khiển), loa (âm thanh).","hs":"- HS hoạt động nhóm, chỉ và nói tên bộ phận; gắn thẻ; ghi nhớ hộp kiến thức."},{"ten":"3. Khám phá: Một số loại máy tính khác","gv":"- GV giới thiệu máy tính xách tay, máy tính bảng, điện thoại thông minh; màn hình cảm ứng là thiết bị nhập.","hs":"- HS nhận biết các loại máy tính; hiểu màn hình cảm ứng thay chức năng chuột và bàn phím."},{"ten":"4. Luyện tập","gv":"- GV cho HS làm bài tập chọn bộ phận cơ bản, bộ phận nhập thông tin (SGK tr.14-15).","hs":"- HS làm bài, chữa bài."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS làm quen với các thiết bị số quanh mình (máy tính để bàn, xách tay, máy tính bảng, điện thoại) và gọi đúng tên bộ phận — nền tảng để sử dụng thiết bị số.\n- (Làm quen AI - mức nhận biết) GV chỉ ra: điện thoại, máy tính bảng ngày nay có trợ lí ảo nghe được lời nói của em — đó là một phần mềm thông minh gắn trong thiết bị.\n⚠ GV thao tác và kiểm soát hoàn toàn; HS quan sát, không tự nhập thông tin cá nhân; dùng công cụ số trung thực, an toàn.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":6,"tiet":6,"bai":"Bài 3: Máy tính và em (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Biết và thực hiện được quy tắc an toàn về điện khi sử dụng máy tính.\n- Có ý thức đề phòng tai nạn về điện; nhận biết việc nên và không nên khi dùng máy tính.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nêu tình huống: phát hiện dây điện của máy tính bị hở, em sẽ làm gì?","hs":"- HS nêu cách xử lí an toàn: không tự chạm, báo thầy cô/người lớn."},{"ten":"2. Khám phá: An toàn về điện","gv":"- GV cho HS quan sát hình SGK, thảo luận việc nên/không nên để bảo đảm an toàn điện.\n- Chốt quy tắc an toàn về điện khi dùng máy tính.","hs":"- HS thảo luận, nêu việc nên làm (giữ tay khô, dùng đúng cách) và không nên (chạm dây hở, cắm nhiều thiết bị); ghi nhớ."},{"ten":"3. Luyện tập","gv":"- GV cho HS xử lí tình huống: dây chuột chưa cắm, có mùi khét từ dây điện... (SGK tr.17).","hs":"- HS chọn cách xử lí đúng: báo thầy cô, ra ngoài báo người lớn."},{"ten":"4. Vận dụng","gv":"- GV: máy tính không nghe được âm thanh thì cần lắp thêm thiết bị gì? Liên hệ an toàn điện ở nhà.","hs":"- HS trả lời (loa/tai nghe) và nêu cách dùng điện an toàn ở nhà."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS hình thành thói quen sử dụng thiết bị số an toàn: giữ gìn thiết bị, dùng điện đúng cách — một yêu cầu cơ bản của người dùng thiết bị số.\n⚠ Dùng thiết bị, phần mềm an toàn dưới sự hướng dẫn của GV.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":7,"tiet":7,"bai":"Bài 4: Làm việc với máy tính (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Biết và ngồi đúng tư thế khi làm việc với máy tính, biết vị trí phù hợp của màn hình.\n- Nêu được tác hại của ngồi sai tư thế hoặc dùng máy tính quá thời gian quy định.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nêu tình huống bạn Khoa thắc mắc: tư thế ngồi và cách cầm chuột thế nào là khoa học?","hs":"- HS thảo luận, nêu hiểu biết ban đầu về tư thế ngồi đúng."},{"ten":"2. Khám phá: Tư thế ngồi","gv":"- GV cho HS quan sát hình SGK, tìm hiểu tư thế ngồi đúng.\n- Chốt: ngồi thẳng lưng, mắt ngang tầm và cách màn hình 50–80 cm, tay ngang bàn phím, hai chân trên sàn.","hs":"- HS thảo luận; nêu tư thế đúng và tác hại của ngồi sai (vẹo cột sống, mỏi mắt); ghi nhớ."},{"ten":"3. Luyện tập","gv":"- GV cho HS chọn tư thế đúng, nêu bệnh có thể tránh khi ngồi đúng (SGK tr.19).","hs":"- HS làm bài, thực hành ngồi đúng tư thế tại chỗ."},{"ten":"4. Vận dụng","gv":"- GV: em hãy luyện tập tư thế ngồi đúng khi học và khi dùng máy tính ở nhà.","hs":"- HS luyện tập, tự điều chỉnh."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS hình thành thói quen an toàn – có văn hoá khi dùng thiết bị số: ngồi đúng tư thế, dùng máy tính đúng thời lượng để bảo vệ sức khoẻ.\n⚠ Dùng thiết bị, phần mềm an toàn dưới sự hướng dẫn của GV.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":8,"tiet":8,"bai":"Bài 4: Làm việc với máy tính (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Biết cầm chuột đúng cách và thực hiện được các thao tác cơ bản: di chuyển, nháy, nháy nút phải, nháy đúp, kéo thả chuột.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Phòng máy/máy chiếu, máy tính đã cài phần mềm, bài giảng điện tử, phiếu học tập.\n- HS: SGK Tin học 3 (KNTT), vở ghi; luân phiên thực hành trên máy tính.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS quan sát con chuột máy tính, nêu các nút của chuột.","hs":"- HS nêu: nút trái, nút phải, nút cuộn."},{"ten":"2. Khám phá: Chuột máy tính","gv":"- GV hướng dẫn cách cầm chuột (tay phải, ngón trỏ nút trái, ngón giữa nút phải) và các thao tác cơ bản.\n- Làm mẫu từng thao tác.","hs":"- HS quan sát, ghi nhớ cách cầm chuột và tên các thao tác: di chuyển, nháy, nháy phải, nháy đúp, kéo thả."},{"ten":"3. Thực hành","gv":"- GV cho HS thực hành cầm chuột, di chuyển con trỏ, nháy chọn biểu tượng, kéo thả trên màn hình nền.","hs":"- HS lần lượt thực hành trên máy; điều khiển con trỏ chuột theo yêu cầu."},{"ten":"4. Luyện tập","gv":"- GV cho HS làm bài tập về thao tác chuột (di chuyển biểu tượng dùng thao tác nào...).","hs":"- HS trả lời: kéo thả chuột; nhận xét bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS thực hành thao tác cơ bản trên máy tính (điều khiển chuột) — kĩ năng nền tảng để sử dụng phần mềm và tạo sản phẩm số sau này.\n- (Làm quen AI - mức nhận biết) GV giới thiệu một số phần mềm/trò chơi luyện chuột giúp em rèn kĩ năng; nhiều phần mềm có hướng dẫn thông minh chỉ ra thao tác đúng/sai.\n⚠ GV thao tác và kiểm soát hoàn toàn; HS quan sát, không tự nhập thông tin cá nhân; dùng công cụ số trung thực, an toàn.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":9,"tiet":9,"bai":"Bài 4: Làm việc với máy tính (Tiết 3)","yccd":"1. Năng lực Tin học (đặc thù):\n- Khởi động được máy tính, kích hoạt được một phần mềm ứng dụng, ra khỏi hệ thống đúng cách.\n- Nêu được ví dụ thao tác không đúng cách gây tổn hại thiết bị.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Phòng máy/máy chiếu, máy tính đã cài phần mềm, bài giảng điện tử, phiếu học tập.\n- HS: SGK Tin học 3 (KNTT), vở ghi; luân phiên thực hành trên máy tính.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nêu: hằng ngày em bật/tắt ti vi thế nào? Với máy tính thì sao?","hs":"- HS chia sẻ; dự đoán cách bật/tắt máy tính."},{"ten":"2. Khám phá – Thực hành: Bật/tắt máy tính","gv":"- GV làm mẫu: bật máy, quan sát màn hình nền; nháy đúp mở phần mềm; tắt máy đúng cách (Start\\Power\\Shut down).","hs":"- HS quan sát rồi thực hành theo từng bước; báo cáo kết quả."},{"ten":"3. Thực hành: Mở và đóng phần mềm","gv":"- GV hướng dẫn HS nháy đúp mở một phần mềm, thao tác đơn giản, rồi đóng phần mềm.","hs":"- HS thực hành mở/đóng phần mềm; nêu thao tác sai có thể gây hỏng thiết bị."},{"ten":"4. Luyện tập – Vận dụng","gv":"- GV cho HS làm bài tập chọn thao tác tắt máy đúng; nhắc tắt máy đúng cách ở nhà.","hs":"- HS làm bài; về nhà luyện bật/tắt máy đúng cách (nếu có điều kiện)."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS thực hành làm chủ thao tác cơ bản với máy tính (khởi động – mở phần mềm – tắt máy an toàn), sẵn sàng cho việc tạo sản phẩm số.\n- (Làm quen AI - mức nhận biết) GV cho HS xem: nhiều phần mềm hiện nay có gợi ý thông minh (nút trợ giúp) hướng dẫn người dùng từng bước.\n⚠ GV thao tác và kiểm soát hoàn toàn; HS quan sát, không tự nhập thông tin cá nhân; dùng công cụ số trung thực, an toàn.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":10,"tiet":10,"bai":"Bài 5: Sử dụng bàn phím (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Chỉ ra được khu vực chính của bàn phím và gọi được tên các hàng phím.\n- Biết vị trí hàng phím cơ sở và hai phím có gai F, J.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS quan sát bàn phím, đoán bàn phím có những hàng phím nào.","hs":"- HS quan sát, nêu dự đoán về các hàng phím."},{"ten":"2. Khám phá: Khu vực chính và các hàng phím","gv":"- GV giới thiệu khu vực chính của bàn phím và tên các hàng: hàng cơ sở, hàng trên, hàng dưới, hàng phím số, hàng phím cách.\n- Chỉ hai phím có gai F, J trên hàng cơ sở.","hs":"- HS quan sát, gọi tên các hàng phím; nhận biết hai phím có gai F, J; ghi nhớ."},{"ten":"3. Luyện tập","gv":"- GV cho HS chỉ và gọi tên hàng phím trên hình/bàn phím thật.","hs":"- HS chỉ đúng các hàng phím; nhận xét bạn."},{"ten":"4. Vận dụng","gv":"- GV: hãy tìm hai phím có gai trên bàn phím máy tính ở lớp/ở nhà và đặt ngón trỏ vào đó.","hs":"- HS thực hành đặt tay đúng vị trí."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS làm quen với bàn phím — thiết bị nhập quan trọng để soạn thảo, tạo nội dung số.\n⚠ Dùng thiết bị, phần mềm an toàn dưới sự hướng dẫn của GV.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":11,"tiet":11,"bai":"Bài 5: Sử dụng bàn phím (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Biết đặt các ngón tay đúng vị trí trên hàng phím cơ sở.\n- Thực hiện được thao tác gõ phím ở hàng cơ sở, hàng trên, hàng dưới đúng quy định.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Phòng máy/máy chiếu, máy tính đã cài phần mềm, bài giảng điện tử, phiếu học tập.\n- HS: SGK Tin học 3 (KNTT), vở ghi; luân phiên thực hành trên máy tính.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS đặt hai ngón trỏ vào phím có gai F, J.","hs":"- HS đặt tay đúng vị trí xuất phát trên hàng phím cơ sở."},{"ten":"2. Khám phá: Vị trí đặt ngón tay","gv":"- GV hướng dẫn quy tắc đặt tám ngón tay trên hàng cơ sở và cách vươn ngón gõ các hàng khác.","hs":"- HS quan sát, đặt ngón tay đúng quy định; ghi nhớ."},{"ten":"3. Thực hành gõ phím","gv":"- GV cho HS thực hành gõ các phím hàng cơ sở, hàng trên, hàng dưới bằng phần mềm luyện gõ (nếu có) hoặc soạn thảo đơn giản.","hs":"- HS thực hành gõ phím đúng ngón; báo cáo kết quả."},{"ten":"4. Luyện tập – Vận dụng","gv":"- GV cho HS gõ một vài từ ngắn; về nhà luyện gõ 10 ngón nếu có máy.","hs":"- HS luyện gõ; tự điều chỉnh tư thế tay."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS thực hành thao tác gõ bàn phím đúng cách trên phần mềm — kĩ năng cơ bản để soạn thảo và tạo nội dung số.\n- (Làm quen AI - mức nhận biết) GV giới thiệu phần mềm luyện gõ có chấm điểm, báo lỗi tự động — công cụ thông minh giúp em tự luyện tập và tiến bộ.\n⚠ GV thao tác và kiểm soát hoàn toàn; HS quan sát, không tự nhập thông tin cá nhân; dùng công cụ số trung thực, an toàn.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":12,"tiet":12,"bai":"Bài 6: Khám phá thông tin trên Internet (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nêu được ví dụ về tin tức, chương trình giải trí có thể xem khi truy cập Internet.\n- Nêu được ví dụ thông tin không có sẵn trong máy nhưng tìm được trên Internet.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV hỏi: em đã từng xem gì trên Internet? (phim hoạt hình, bài hát, tin tức...).","hs":"- HS chia sẻ trải nghiệm xem tin tức, giải trí trên Internet."},{"ten":"2. Khám phá: Thông tin trên Internet","gv":"- GV giới thiệu Internet là kho thông tin lớn; nêu ví dụ tin tức, chương trình giải trí, thông tin không có sẵn trong máy.\n- Chốt kiến thức.","hs":"- HS nêu ví dụ thông tin tìm được trên Internet mà máy tính không có sẵn; ghi nhớ."},{"ten":"3. Luyện tập","gv":"- GV cho HS kể thêm ví dụ thông tin học tập, giải trí có trên Internet.","hs":"- HS làm việc nhóm, trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS làm quen với Internet như một nguồn học liệu số phong phú; GV thao tác mở một trang thông tin an toàn cho HS quan sát.\n- (Làm quen AI - mức nhận biết) GV giới thiệu công cụ tìm kiếm và trợ lí ảo có thể trả lời câu hỏi, gợi ý thông tin; GV nhập từ khoá mẫu, HS quan sát.\n⚠ GV thao tác và kiểm soát hoàn toàn; HS quan sát, không tự nhập thông tin cá nhân; dùng công cụ số trung thực, an toàn.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":13,"tiet":13,"bai":"Bài 6: Khám phá thông tin trên Internet (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Biết được không phải thông tin nào trên Internet cũng phù hợp với lứa tuổi.\n- Có ý thức truy cập Internet an toàn, chọn lọc thông tin phù hợp.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nêu tình huống: khi lên mạng gặp nội dung không phù hợp, em nên làm gì?","hs":"- HS thảo luận, nêu cách xử lí ban đầu."},{"ten":"2. Khám phá: An toàn khi truy cập Internet","gv":"- GV hướng dẫn: chỉ xem nội dung phù hợp lứa tuổi, có người lớn hướng dẫn; không tin ngay mọi thông tin.\n- Chốt kiến thức.","hs":"- HS nêu việc nên/không nên khi lên Internet; ghi nhớ."},{"ten":"3. Luyện tập","gv":"- GV cho HS xử lí tình huống: gặp quảng cáo lạ, nội dung không phù hợp, người lạ nhắn tin.","hs":"- HS chọn cách xử lí an toàn: rời khỏi, báo người lớn."},{"ten":"4. Vận dụng","gv":"- GV: khi cần tìm thông tin cho bài học, em nhờ ai giúp và chọn nguồn nào?","hs":"- HS chia sẻ; nêu ý thức nhờ thầy cô, bố mẹ hướng dẫn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS hình thành năng lực ứng xử có văn hoá và an toàn trên môi trường số: chọn lọc thông tin phù hợp, bảo vệ bản thân khi lên mạng.\n- (Làm quen AI - mức nhận biết) GV lưu ý: kết quả từ công cụ tìm kiếm hay trợ lí ảo không phải lúc nào cũng đúng và phù hợp; cần người lớn kiểm tra, chọn lọc.\n⚠ GV thao tác và kiểm soát hoàn toàn; HS quan sát, không tự nhập thông tin cá nhân; dùng công cụ số trung thực, an toàn.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":14,"tiet":14,"bai":"Bài 7: Sắp xếp để dễ tìm kiếm (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Giải thích được: sắp xếp hợp lí thì khi cần sẽ tìm được nhanh hơn.\n- Sắp xếp được đồ vật hay dữ liệu hợp lí theo một số yêu cầu cụ thể.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nêu tình huống: giá sách lộn xộn và giá sách xếp gọn, tìm quyển sách ở đâu nhanh hơn?","hs":"- HS trả lời: giá sách xếp gọn dễ tìm hơn; nêu lí do."},{"ten":"2. Khám phá: Vì sao cần sắp xếp","gv":"- GV cho HS thảo luận: sắp xếp hợp lí giúp tìm nhanh; nêu cách sắp xếp theo nhóm, theo thứ tự.\n- Chốt kiến thức.","hs":"- HS nêu ví dụ sắp xếp sách, đồ dùng; ghi nhớ hộp kiến thức."},{"ten":"3. Luyện tập","gv":"- GV cho HS sắp xếp một nhóm đồ vật/dữ liệu theo yêu cầu (theo màu, theo tên, theo loại).","hs":"- HS thực hiện sắp xếp, trình bày cách làm."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS hiểu nguyên tắc sắp xếp, phân loại — nền tảng để tổ chức dữ liệu trong máy tính; GV minh hoạ danh sách sắp xếp trên máy chiếu.\n⚠ Dùng thiết bị, phần mềm an toàn dưới sự hướng dẫn của GV.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":15,"tiet":15,"bai":"Bài 7: Sắp xếp để dễ tìm kiếm (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nêu được cách tìm đúng và nhanh đối tượng cần tìm dựa trên sự sắp xếp.\n- Vận dụng sắp xếp và tìm kiếm trong tình huống thực tế.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS thi tìm một quyển sách trong giá đã sắp xếp và giá chưa sắp xếp.","hs":"- HS tham gia, nhận ra giá đã sắp xếp tìm nhanh hơn."},{"ten":"2. Khám phá: Tìm kiếm dựa trên sắp xếp","gv":"- GV hướng dẫn cách tìm nhanh dựa trên trật tự đã sắp xếp (theo bảng chữ cái, theo số...).\n- Chốt kiến thức.","hs":"- HS nêu cách tìm nhanh; ghi nhớ."},{"ten":"3. Luyện tập","gv":"- GV cho HS tìm một đối tượng trong danh sách đã sắp xếp theo yêu cầu.","hs":"- HS thực hiện, giải thích cách tìm."},{"ten":"4. Vận dụng","gv":"- GV: hãy sắp xếp góc học tập/tủ sách của em để dễ tìm.","hs":"- HS thực hiện ở nhà, chia sẻ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS liên hệ việc sắp xếp – tìm kiếm ngoài đời với cách máy tính lưu và tìm dữ liệu nhanh trong thư mục, danh sách.\n- (Làm quen AI - mức nhận biết) GV minh hoạ: khi ta gõ từ khoá, máy tính/công cụ tìm kiếm sắp xếp và tìm kết quả rất nhanh nhờ dữ liệu được tổ chức hợp lí.\n⚠ GV thao tác và kiểm soát hoàn toàn; HS quan sát, không tự nhập thông tin cá nhân; dùng công cụ số trung thực, an toàn.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":16,"tiet":16,"bai":"Bài 8: Sơ đồ hình cây. Tổ chức thông tin trong máy tính (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Biết có thể biểu diễn một cách sắp xếp, phân loại bằng sơ đồ hình cây.\n- Đọc và vẽ được sơ đồ hình cây đơn giản.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS quan sát sơ đồ phân loại (cây gia đình, phân loại con vật).","hs":"- HS quan sát, nhận ra cách biểu diễn phân nhánh."},{"ten":"2. Khám phá: Sơ đồ hình cây","gv":"- GV giới thiệu sơ đồ hình cây: gốc, các nhánh, các cấp; dùng để biểu diễn sắp xếp, phân loại.\n- Chốt kiến thức.","hs":"- HS đọc sơ đồ hình cây; nêu quan hệ các mức; ghi nhớ."},{"ten":"3. Luyện tập","gv":"- GV cho HS vẽ sơ đồ hình cây đơn giản (phân loại đồ dùng học tập, ảnh gia đình).","hs":"- HS vẽ sơ đồ, trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS làm quen với cách tổ chức thông tin theo cấu trúc cây — chính là cách máy tính sắp xếp thư mục và tệp.\n⚠ Dùng thiết bị, phần mềm an toàn dưới sự hướng dẫn của GV.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":17,"tiet":17,"bai":"Bài 8: Sơ đồ hình cây. Tổ chức thông tin trong máy tính (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nhận biết được tệp, thư mục và ổ đĩa trong máy tính.\n- Mô tả được sơ lược vai trò của cấu trúc cây thư mục trong việc lưu trữ tệp và thư mục.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nêu: máy tính lưu ảnh, bài hát, bài học ở đâu và sắp xếp thế nào?","hs":"- HS dự đoán; liên hệ với sơ đồ hình cây đã học."},{"ten":"2. Khám phá: Tệp, thư mục, ổ đĩa","gv":"- GV giới thiệu tệp (tập tin), thư mục (chứa tệp và thư mục con), ổ đĩa; cây thư mục giúp lưu trữ có tổ chức.\n- Chốt kiến thức.","hs":"- HS nhận biết tệp, thư mục, ổ đĩa; hiểu cây thư mục; ghi nhớ."},{"ten":"3. Luyện tập","gv":"- GV cho HS đọc một cây thư mục, xác định thư mục chứa tệp cần tìm.","hs":"- HS đọc cây thư mục, chỉ đúng vị trí."},{"ten":"4. Vận dụng","gv":"- GV: hãy vẽ cây thư mục để sắp xếp ảnh, bài học của em cho dễ tìm.","hs":"- HS vẽ, chia sẻ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS hiểu cách máy tính tổ chức, lưu trữ thông tin theo cây thư mục — năng lực số cơ bản để quản lí dữ liệu.\n- (Làm quen AI - mức nhận biết) GV minh hoạ trên máy tính cấu trúc thư mục thật; giới thiệu chức năng tìm kiếm tệp thông minh trong máy.\n⚠ GV thao tác và kiểm soát hoàn toàn; HS quan sát, không tự nhập thông tin cá nhân; dùng công cụ số trung thực, an toàn.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":18,"tiet":18,"bai":"Ôn tập giữa học kì I","yccd":"1. Năng lực Tin học (đặc thù):\n- Hệ thống hoá kiến thức các chủ đề đã học: thông tin và quyết định, xử lí thông tin, máy tính và em, bàn phím, Internet, sắp xếp – tổ chức thông tin.\n- Vận dụng làm bài kiểm tra, tự đánh giá kết quả học tập.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV tổ chức trò chơi ôn tập nhanh: hỏi – đáp về máy tính, thông tin, bàn phím.","hs":"- HS tham gia trả lời, nhớ lại kiến thức đã học."},{"ten":"2. Ôn tập kiến thức","gv":"- GV hệ thống lại kiến thức trọng tâm bằng sơ đồ tư duy/bảng tổng hợp.","hs":"- HS nhắc lại các đơn vị kiến thức; nêu ví dụ minh hoạ."},{"ten":"3. Luyện tập – Kiểm tra","gv":"- GV cho HS làm phiếu ôn tập/bài kiểm tra ngắn (trắc nghiệm + thực hành nếu có phòng máy).","hs":"- HS làm bài, tự đánh giá và đánh giá bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS ôn lại các thao tác số cơ bản đã thực hành (chuột, bàn phím, tổ chức thư mục) và ý thức an toàn khi dùng máy tính, Internet.\n⚠ Dùng thiết bị, phần mềm an toàn dưới sự hướng dẫn của GV.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":19,"tiet":19,"bai":"Bài 9: Thực hành với tệp và thư mục trong máy tính (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Tìm hiểu được cấu trúc cây của một thư mục để biết nó chứa những thư mục con, tệp nào.\n- Mở được cửa sổ làm việc với tệp và thư mục.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Phòng máy/máy chiếu, máy tính đã cài phần mềm, bài giảng điện tử, phiếu học tập.\n- HS: SGK Tin học 3 (KNTT), vở ghi; luân phiên thực hành trên máy tính.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nêu tình huống bạn An, Khoa muốn thực hành tạo thư mục lưu ảnh gia đình trên máy tính.","hs":"- HS hình dung công việc; sẵn sàng thực hành."},{"ten":"2. Khám phá – Thực hành: Mở cấu trúc thư mục","gv":"- GV làm mẫu: nháy đúp biểu tượng This PC, mở cửa sổ tệp và thư mục; giới thiệu cấu trúc cây thư mục.","hs":"- HS thực hành mở cửa sổ, quan sát thư mục con và tệp bên trong."},{"ten":"3. Luyện tập","gv":"- GV cho HS tìm một tệp/thư mục theo yêu cầu dựa trên cây thư mục.","hs":"- HS tìm đúng vị trí tệp; báo cáo."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS thực hành thao tác quản lí dữ liệu trên máy tính (mở, duyệt cây thư mục) — kĩ năng số thiết thực.\n- (Làm quen AI - mức nhận biết) GV giới thiệu ô tìm kiếm trong cửa sổ thư mục giúp tìm nhanh tệp — một công cụ thông minh hỗ trợ người dùng.\n⚠ GV thao tác và kiểm soát hoàn toàn; HS quan sát, không tự nhập thông tin cá nhân; dùng công cụ số trung thực, an toàn.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":20,"tiet":20,"bai":"Bài 9: Thực hành với tệp và thư mục trong máy tính (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Thực hiện được việc tạo, xoá, đổi tên thư mục.\n- Tìm được tệp ở thư mục cho trước theo yêu cầu.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Phòng máy/máy chiếu, máy tính đã cài phần mềm, bài giảng điện tử, phiếu học tập.\n- HS: SGK Tin học 3 (KNTT), vở ghi; luân phiên thực hành trên máy tính.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS nhắc lại cách mở cửa sổ thư mục ở tiết trước.","hs":"- HS nhắc lại; mở cửa sổ làm việc với thư mục."},{"ten":"2. Khám phá – Thực hành: Thao tác với thư mục","gv":"- GV làm mẫu: tạo thư mục mới, đổi tên thư mục, xoá thư mục.","hs":"- HS thực hành lần lượt: tạo, đổi tên, xoá thư mục theo yêu cầu."},{"ten":"3. Luyện tập","gv":"- GV giao nhiệm vụ: tạo cây thư mục lưu ảnh/bài học theo mẫu; tìm tệp trong thư mục cho trước.","hs":"- HS thực hiện, kiểm tra kết quả."},{"ten":"4. Vận dụng","gv":"- GV: hãy sắp xếp các tệp bài học của em vào thư mục hợp lí để dễ tìm.","hs":"- HS thực hành tổ chức thư mục."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS thực hành tạo và quản lí thư mục trên máy tính — năng lực số quan trọng để lưu trữ, tổ chức sản phẩm học tập.\n⚠ Dùng thiết bị, phần mềm an toàn dưới sự hướng dẫn của GV.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":21,"tiet":21,"bai":"Bài 10: Bảo vệ thông tin khi dùng máy tính (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Biết được thông tin cá nhân và gia đình có thể được lưu trữ, trao đổi nhờ máy tính.\n- Nhận biết những thông tin cần được bảo vệ.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nêu: những thông tin nào về em và gia đình được lưu trong máy tính, điện thoại?","hs":"- HS kể: ảnh, tên, địa chỉ, số điện thoại..."},{"ten":"2. Khám phá: Thông tin cần bảo vệ","gv":"- GV hướng dẫn nhận biết thông tin cá nhân, gia đình cần giữ kín (họ tên, địa chỉ, số điện thoại, mật khẩu, hình ảnh).\n- Chốt kiến thức.","hs":"- HS nêu thông tin cần bảo vệ; hiểu vì sao cần giữ kín; ghi nhớ."},{"ten":"3. Luyện tập","gv":"- GV cho HS phân loại: thông tin nào có thể chia sẻ, thông tin nào cần giữ kín.","hs":"- HS phân loại, giải thích."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS hình thành ý thức bảo vệ dữ liệu cá nhân trên môi trường số — một năng lực số và phẩm chất quan trọng của công dân số.\n- (Làm quen AI - mức nhận biết) GV lưu ý: không cung cấp thông tin cá nhân cho phần mềm, trang web hay người lạ trên mạng, kể cả khi được hỏi.\n⚠ GV thao tác và kiểm soát hoàn toàn; HS quan sát, không tự nhập thông tin cá nhân; dùng công cụ số trung thực, an toàn.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":22,"tiet":22,"bai":"Bài 10: Bảo vệ thông tin khi dùng máy tính (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Có ý thức bảo vệ thông tin cá nhân và gia đình khi giao tiếp qua máy tính.\n- Biết người xấu có thể lợi dụng thông tin để gây hại và cách phòng tránh.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nêu tình huống: người lạ trên mạng hỏi tên, địa chỉ, trường học của em thì em làm gì?","hs":"- HS thảo luận, nêu cách ứng xử."},{"ten":"2. Khám phá: Phòng tránh nguy cơ","gv":"- GV hướng dẫn: không chia sẻ thông tin cá nhân với người lạ; báo người lớn khi gặp tình huống đáng ngờ.\n- Chốt kiến thức.","hs":"- HS nêu việc nên/không nên khi giao tiếp qua máy tính; ghi nhớ."},{"ten":"3. Luyện tập","gv":"- GV cho HS xử lí các tình huống: người lạ kết bạn, đường liên kết lạ, yêu cầu gửi ảnh...","hs":"- HS chọn cách xử lí an toàn: từ chối, báo người lớn."},{"ten":"4. Vận dụng","gv":"- GV: hãy nhắc người thân cùng giữ an toàn thông tin khi dùng máy tính, điện thoại.","hs":"- HS chia sẻ với gia đình."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS củng cố năng lực ứng xử an toàn, có trách nhiệm trên môi trường số; biết tự bảo vệ và bảo vệ gia đình.\n- (Làm quen AI - mức nhận biết) GV lưu ý: một số công cụ thông minh có thể ghi lại điều em nói/gõ; vì vậy cần cẩn trọng, không cung cấp thông tin riêng tư.\n⚠ GV thao tác và kiểm soát hoàn toàn; HS quan sát, không tự nhập thông tin cá nhân; dùng công cụ số trung thực, an toàn.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":23,"tiet":23,"bai":"Bài 11: Bài trình chiếu của em (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nhận biết được biểu tượng của phần mềm trình chiếu và khởi động được phần mềm.\n- Tạo được tệp trình chiếu, thêm được trang chiếu mới.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Phòng máy/máy chiếu, máy tính đã cài phần mềm, bài giảng điện tử, phiếu học tập.\n- HS: SGK Tin học 3 (KNTT), vở ghi; luân phiên thực hành trên máy tính.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS xem một bài trình chiếu đơn giản (ảnh + chữ) trên máy chiếu.","hs":"- HS quan sát, nêu mong muốn tự tạo bài trình chiếu."},{"ten":"2. Khám phá – Thực hành: Khởi động và tạo tệp","gv":"- GV giới thiệu biểu tượng phần mềm trình chiếu; làm mẫu khởi động, tạo tệp mới, thêm trang chiếu.","hs":"- HS thực hành: mở phần mềm, tạo tệp trình chiếu, thêm trang chiếu mới."},{"ten":"3. Luyện tập","gv":"- GV cho HS tạo bài trình chiếu có 2–3 trang chiếu theo mẫu.","hs":"- HS thực hành, kiểm tra kết quả."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS thực hành tạo một sản phẩm số đơn giản (bài trình chiếu) — đúng miền năng lực Ứng dụng và sáng tạo nội dung số.\n- (Làm quen AI - mức nhận biết) GV giới thiệu: phần mềm trình chiếu hiện đại có gợi ý bố cục, chọn ảnh tự động (công cụ thông minh); GV thao tác mẫu cho HS xem.\n⚠ GV thao tác và kiểm soát hoàn toàn; HS quan sát, không tự nhập thông tin cá nhân; dùng công cụ số trung thực, an toàn.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":24,"tiet":24,"bai":"Bài 11: Bài trình chiếu của em (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Gõ được một vài dòng văn bản vào trang chiếu.\n- Lưu và đặt được tên cho tệp trình chiếu.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Phòng máy/máy chiếu, máy tính đã cài phần mềm, bài giảng điện tử, phiếu học tập.\n- HS: SGK Tin học 3 (KNTT), vở ghi; luân phiên thực hành trên máy tính.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS mở lại tệp trình chiếu đã tạo ở tiết trước.","hs":"- HS mở tệp, sẵn sàng thực hành tiếp."},{"ten":"2. Khám phá – Thực hành: Gõ văn bản và lưu tệp","gv":"- GV hướng dẫn gõ vài dòng văn bản vào trang chiếu; làm mẫu lưu tệp và đặt tên.","hs":"- HS thực hành gõ văn bản, lưu tệp và đặt tên có nghĩa."},{"ten":"3. Luyện tập","gv":"- GV cho HS hoàn thiện bài trình chiếu giới thiệu bản thân/gia đình (chữ + hình).","hs":"- HS thực hành, lưu lại sản phẩm."},{"ten":"4. Vận dụng","gv":"- GV cho vài HS trình chiếu sản phẩm; cả lớp nhận xét.","hs":"- HS trình bày sản phẩm số của mình; nhận xét bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS hoàn thiện và lưu trữ một sản phẩm số cá nhân, biết đặt tên tệp có nghĩa để dễ tìm — năng lực tạo và quản lí nội dung số.\n- (Làm quen AI - mức nhận biết) GV giới thiệu công cụ soạn thảo có tự sửa lỗi chính tả, gợi ý từ; nhắc HS kiểm tra lại vì gợi ý không phải lúc nào cũng đúng.\n⚠ GV thao tác và kiểm soát hoàn toàn; HS quan sát, không tự nhập thông tin cá nhân; dùng công cụ số trung thực, an toàn.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":25,"tiet":25,"bai":"Bài 12: Tìm hiểu về giới tự nhiên (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nhận thấy nhờ máy tính mà con người quan sát và biết thêm về giới tự nhiên một cách sinh động, trực quan.\n- Kể lại được những hiểu biết mới khi quan sát qua phần mềm.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Phòng máy/máy chiếu, máy tính đã cài phần mềm, bài giảng điện tử, phiếu học tập.\n- HS: SGK Tin học 3 (KNTT), vở ghi; luân phiên thực hành trên máy tính.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nêu: em muốn tìm hiểu về loài vật, cây cối, biển sâu... làm cách nào để thấy rõ?","hs":"- HS chia sẻ; mong muốn quan sát qua máy tính."},{"ten":"2. Khám phá – Thực hành: Quan sát giới tự nhiên","gv":"- GV mở phần mềm/hình ảnh, video số về động vật, thực vật, hiện tượng tự nhiên cho HS quan sát.","hs":"- HS quan sát, nêu điều mới mẻ, thú vị đã thấy."},{"ten":"3. Luyện tập","gv":"- GV cho HS chọn một đối tượng tự nhiên, quan sát và kể lại đặc điểm.","hs":"- HS thực hành quan sát, kể lại hiểu biết mới."},{"ten":"4. Vận dụng","gv":"- GV: hãy nhờ người lớn cùng xem thêm một video về thiên nhiên phù hợp lứa tuổi.","hs":"- HS thực hiện ở nhà, chia sẻ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS khai thác học liệu số (hình ảnh, video, phần mềm mô phỏng) để tìm hiểu giới tự nhiên trực quan, sinh động.\n- (Làm quen AI - mức nhận biết) GV giới thiệu: có ứng dụng thông minh nhận diện được cây, con vật qua ảnh; GV thao tác minh hoạ, HS quan sát và nhận xét.\n⚠ GV thao tác và kiểm soát hoàn toàn; HS quan sát, không tự nhập thông tin cá nhân; dùng công cụ số trung thực, an toàn.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":26,"tiet":26,"bai":"Bài 13: Luyện tập sử dụng chuột (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Cầm chuột đúng cách; thực hiện thành thạo các thao tác: di chuyển, nháy, kéo thả, nháy nút phải, nháy đúp, dùng nút cuộn.\n- Nhận thấy phần mềm hướng dẫn thao tác đúng với chuột.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Phòng máy/máy chiếu, máy tính đã cài phần mềm, bài giảng điện tử, phiếu học tập.\n- HS: SGK Tin học 3 (KNTT), vở ghi; luân phiên thực hành trên máy tính.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS nhắc lại các thao tác với chuột đã học.","hs":"- HS nêu các thao tác; cầm chuột đúng cách."},{"ten":"2. Khám phá – Thực hành: Luyện thao tác chuột","gv":"- GV mở phần mềm luyện chuột (trò chơi kéo thả, nháy đúp...); hướng dẫn HS thực hành.","hs":"- HS thực hành từng thao tác chuột qua phần mềm."},{"ten":"3. Luyện tập","gv":"- GV tổ chức thi thao tác chuột nhanh, đúng theo phần mềm.","hs":"- HS luyện tập, cải thiện tốc độ và độ chính xác."},{"ten":"4. Vận dụng","gv":"- GV: nếu có máy ở nhà, em luyện thêm để thao tác chuột thành thạo.","hs":"- HS luyện tập thêm."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS rèn kĩ năng thao tác chuột thành thạo qua phần mềm — nền tảng để sử dụng mọi phần mềm và tạo sản phẩm số.\n- (Làm quen AI - mức nhận biết) GV chỉ ra: phần mềm tự chấm điểm, báo thao tác đúng/sai để em tự điều chỉnh — đó là công cụ hỗ trợ thông minh.\n⚠ GV thao tác và kiểm soát hoàn toàn; HS quan sát, không tự nhập thông tin cá nhân; dùng công cụ số trung thực, an toàn.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":27,"tiet":27,"bai":"Ôn tập, kiểm tra học kì (Chủ đề E)","yccd":"1. Năng lực Tin học (đặc thù):\n- Củng cố kĩ năng thực hành: tạo bài trình chiếu, quan sát giới tự nhiên qua phần mềm, luyện chuột.\n- Vận dụng làm bài kiểm tra thực hành/trắc nghiệm, tự đánh giá.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Phòng máy/máy chiếu, máy tính đã cài phần mềm, bài giảng điện tử, phiếu học tập.\n- HS: SGK Tin học 3 (KNTT), vở ghi; luân phiên thực hành trên máy tính.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV tổ chức hỏi – đáp nhanh ôn lại kiến thức, kĩ năng đã học.","hs":"- HS trả lời, nhớ lại nội dung."},{"ten":"2. Ôn tập","gv":"- GV hệ thống kĩ năng: thao tác chuột, bàn phím, tạo/lưu tệp trình chiếu, tổ chức thư mục.","hs":"- HS nhắc lại quy trình các thao tác."},{"ten":"3. Luyện tập – Kiểm tra","gv":"- GV cho HS làm bài kiểm tra (thực hành trên máy nếu có phòng máy, hoặc trắc nghiệm).","hs":"- HS làm bài, tự đánh giá và đánh giá bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS thể hiện năng lực số đã hình thành: thao tác thiết bị, tạo sản phẩm số đơn giản, dùng máy tính an toàn.\n⚠ Dùng thiết bị, phần mềm an toàn dưới sự hướng dẫn của GV.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":28,"tiet":28,"bai":"Bài 14: Em thực hiện công việc như thế nào (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nêu được một số công việc hằng ngày có thể thực hiện theo từng bước, các bước sắp xếp theo thứ tự.\n- Sắp xếp được các bước của một công việc quen thuộc.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nêu: để pha một cốc nước cam, em làm những bước nào, theo thứ tự ra sao?","hs":"- HS kể các bước; nhận ra cần làm theo thứ tự."},{"ten":"2. Khám phá: Công việc gồm nhiều bước","gv":"- GV hướng dẫn: một công việc gồm nhiều bước, mỗi bước là một việc nhỏ, phải sắp xếp đúng thứ tự.\n- Chốt kiến thức.","hs":"- HS nêu ví dụ công việc và các bước; ghi nhớ."},{"ten":"3. Luyện tập","gv":"- GV cho HS sắp xếp lại các bước của một công việc bị đảo lộn (đánh răng, gấp áo...).","hs":"- HS sắp xếp đúng thứ tự các bước, giải thích."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS làm quen tư duy chia công việc thành các bước theo thứ tự — nền tảng của tư duy thuật toán, cách máy tính thực hiện công việc.\n- (Làm quen AI - mức nhận biết) GV nêu: máy tính, robot làm việc bằng cách thực hiện lần lượt các bước con người sắp xếp cho nó.\n⚠ GV thao tác và kiểm soát hoàn toàn; HS quan sát, không tự nhập thông tin cá nhân; dùng công cụ số trung thực, an toàn.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":29,"tiet":29,"bai":"Bài 14: Em thực hiện công việc như thế nào (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nhận biết được nên chia một việc thành những việc nhỏ hơn để dễ hiểu, dễ thực hiện.\n- Nêu được ví dụ về một việc có thể chia thành những việc nhỏ hơn.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nêu công việc lớn: chuẩn bị cho buổi liên hoan lớp; làm thế nào cho dễ?","hs":"- HS đề xuất chia thành các việc nhỏ."},{"ten":"2. Khám phá: Chia việc lớn thành việc nhỏ","gv":"- GV hướng dẫn cách chia một việc thành các việc nhỏ hơn để dễ thực hiện.\n- Chốt kiến thức.","hs":"- HS nêu ví dụ chia việc; ghi nhớ."},{"ten":"3. Luyện tập","gv":"- GV cho HS chia một công việc cụ thể thành các việc nhỏ và sắp xếp thứ tự.","hs":"- HS thực hiện, trình bày."},{"ten":"4. Vận dụng","gv":"- GV: hãy chia công việc chuẩn bị đi học buổi sáng của em thành các bước.","hs":"- HS thực hiện, chia sẻ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS rèn tư duy phân rã công việc — bước quan trọng để sau này mô tả nhiệm vụ cho máy tính giải quyết.\n- (Làm quen AI - mức nhận biết) GV liên hệ: để máy tính giúp một việc, con người phải chia việc thành các bước rõ ràng cho máy làm theo.\n⚠ GV thao tác và kiểm soát hoàn toàn; HS quan sát, không tự nhập thông tin cá nhân; dùng công cụ số trung thực, an toàn.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":30,"tiet":30,"bai":"Bài 15: Công việc được thực hiện theo điều kiện (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Biết một việc có được thực hiện hay không tuỳ thuộc vào điều kiện.\n- Nhận biết điều kiện trong tình huống quen thuộc.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nêu: Nếu trời mưa thì em mang áo mưa; nếu trời nắng thì em đội mũ. Việc làm phụ thuộc điều gì?","hs":"- HS trả lời: phụ thuộc điều kiện thời tiết."},{"ten":"2. Khám phá: Công việc theo điều kiện","gv":"- GV hướng dẫn: một việc được thực hiện hay không tuỳ thuộc điều kiện; nêu nhiều ví dụ.\n- Chốt kiến thức.","hs":"- HS nêu ví dụ công việc phụ thuộc điều kiện; ghi nhớ."},{"ten":"3. Luyện tập","gv":"- GV cho HS xác định điều kiện trong các tình huống cho trước.","hs":"- HS chỉ ra điều kiện và việc được thực hiện."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS làm quen khái niệm điều kiện (Nếu... thì...) — nền tảng của cách máy tính ra quyết định theo điều kiện.\n- (Làm quen AI - mức nhận biết) GV nêu: thiết bị thông minh cũng hoạt động theo điều kiện, ví dụ Nếu trời tối thì đèn tự bật.\n⚠ GV thao tác và kiểm soát hoàn toàn; HS quan sát, không tự nhập thông tin cá nhân; dùng công cụ số trung thực, an toàn.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":31,"tiet":31,"bai":"Bài 15: Công việc được thực hiện theo điều kiện (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Sử dụng được cách nói \"Nếu... thì...\" để diễn đạt một việc có được thực hiện hay không tuỳ thuộc điều kiện.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Máy tính, máy chiếu, bài giảng điện tử (PowerPoint), tranh ảnh minh hoạ.\n- HS: SGK Tin học 3 (KNTT), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS đặt câu Nếu... thì... với tình huống quen thuộc.","hs":"- HS đặt câu Nếu... thì... về sinh hoạt hằng ngày."},{"ten":"2. Khám phá: Diễn đạt điều kiện","gv":"- GV hướng dẫn dùng mẫu Nếu <điều kiện> thì <việc làm> để diễn đạt.\n- Chốt kiến thức.","hs":"- HS luyện diễn đạt bằng mẫu Nếu... thì...; ghi nhớ."},{"ten":"3. Luyện tập","gv":"- GV cho HS viết các câu Nếu... thì... cho tình huống cho trước.","hs":"- HS viết câu, trình bày, nhận xét."},{"ten":"4. Vận dụng","gv":"- GV: hãy nêu 2 việc ở nhà em thực hiện theo điều kiện bằng mẫu Nếu... thì...","hs":"- HS thực hiện, chia sẻ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS diễn đạt điều kiện bằng ngôn ngữ Nếu... thì... — cách con người mô tả quy tắc cho máy tính hoạt động.\n- (Làm quen AI - mức nhận biết) GV liên hệ: người lập trình dùng câu Nếu... thì... để chỉ cho máy tính, robot biết khi nào cần làm gì.\n⚠ GV thao tác và kiểm soát hoàn toàn; HS quan sát, không tự nhập thông tin cá nhân; dùng công cụ số trung thực, an toàn.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":32,"tiet":32,"bai":"Bài 16: Công việc của em và sự trợ giúp của máy tính (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Phát biểu được nhiệm vụ đặt ra: xác định cái đã cho, cần làm gì, cần tạo ra sản phẩm số nào.\n- Chia được một công việc thành những việc nhỏ hơn, trong đó có việc thực hiện với trợ giúp của máy tính.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Phòng máy/máy chiếu, máy tính đã cài phần mềm, bài giảng điện tử, phiếu học tập.\n- HS: SGK Tin học 3 (KNTT), vở ghi; luân phiên thực hành trên máy tính.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nêu nhiệm vụ: làm một tấm thiệp/bài giới thiệu về con vật em yêu thích. Cần những gì?","hs":"- HS xác định: đã có thông tin gì, cần làm gì, sản phẩm là gì."},{"ten":"2. Khám phá: Xác định và chia nhiệm vụ","gv":"- GV hướng dẫn phát biểu nhiệm vụ và chia thành các việc nhỏ; chỉ rõ việc nào máy tính giúp được.\n- Chốt kiến thức.","hs":"- HS phát biểu nhiệm vụ, chia việc; xác định việc dùng máy tính (tìm ảnh, gõ chữ, trình chiếu)."},{"ten":"3. Luyện tập","gv":"- GV cho HS lập kế hoạch các bước cho một nhiệm vụ nhỏ có dùng máy tính.","hs":"- HS lập các bước, trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS biết xác định nhiệm vụ và phân công việc nào cần đến máy tính — năng lực giải quyết vấn đề với hỗ trợ của công nghệ số.\n- (Làm quen AI - mức nhận biết) GV giới thiệu công cụ số hỗ trợ: tìm ảnh, tạo bài trình chiếu; nêu rõ máy tính chỉ giúp, con người quyết định và kiểm tra kết quả.\n⚠ GV thao tác và kiểm soát hoàn toàn; HS quan sát, không tự nhập thông tin cá nhân; dùng công cụ số trung thực, an toàn.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":33,"tiet":33,"bai":"Bài 16: Công việc của em và sự trợ giúp của máy tính (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Thực hiện được nhiệm vụ do giáo viên đặt ra, có sử dụng máy tính.\n- Tạo được một sản phẩm số đơn giản hoàn chỉnh.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Phòng máy/máy chiếu, máy tính đã cài phần mềm, bài giảng điện tử, phiếu học tập.\n- HS: SGK Tin học 3 (KNTT), vở ghi; luân phiên thực hành trên máy tính.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nhắc lại nhiệm vụ và các bước đã lập ở tiết trước.","hs":"- HS nhắc lại kế hoạch; sẵn sàng thực hành."},{"ten":"2. Khám phá – Thực hành: Thực hiện nhiệm vụ","gv":"- GV cho HS thực hiện các bước có dùng máy tính: tìm/chèn ảnh, gõ chữ, tạo bài trình chiếu đơn giản.","hs":"- HS thực hành từng bước, tạo sản phẩm số theo nhiệm vụ."},{"ten":"3. Luyện tập – Trình bày","gv":"- GV cho HS hoàn thiện, lưu và trình bày sản phẩm; cả lớp nhận xét.","hs":"- HS lưu, trình bày sản phẩm; nhận xét bạn."},{"ten":"4. Vận dụng","gv":"- GV: hãy dùng máy tính giúp em hoàn thành một việc học tập khác (nếu có điều kiện).","hs":"- HS chia sẻ ý tưởng vận dụng."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS hoàn thành một nhiệm vụ thực tế với sự trợ giúp của máy tính, tạo ra sản phẩm số — đích đến của năng lực ứng dụng và sáng tạo nội dung số ở lớp 3.\n- (Làm quen AI - mức nhận biết) GV nêu: nhiều công cụ thông minh có thể giúp gợi ý ý tưởng, chọn ảnh, sửa lỗi; nhưng em cần kiểm tra và chịu trách nhiệm về sản phẩm của mình.\n⚠ GV thao tác và kiểm soát hoàn toàn; HS quan sát, không tự nhập thông tin cá nhân; dùng công cụ số trung thực, an toàn.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":34,"tiet":34,"bai":"Ôn tập cuối năm học","yccd":"1. Năng lực Tin học (đặc thù):\n- Hệ thống hoá toàn bộ kiến thức, kĩ năng Tin học lớp 3: thông tin, máy tính, Internet, tổ chức thông tin, an toàn số, ứng dụng tin học, giải quyết vấn đề.\n- Vận dụng tổng hợp, tự đánh giá sự tiến bộ.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Phòng máy/máy chiếu, máy tính đã cài phần mềm, bài giảng điện tử, phiếu học tập.\n- HS: SGK Tin học 3 (KNTT), vở ghi; luân phiên thực hành trên máy tính.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV tổ chức trò chơi tổng ôn: hỏi – đáp nhanh theo các chủ đề đã học.","hs":"- HS tham gia, nhớ lại kiến thức toàn năm."},{"ten":"2. Ôn tập","gv":"- GV hệ thống kiến thức bằng sơ đồ tư duy các chủ đề A–F.","hs":"- HS nhắc lại nội dung trọng tâm từng chủ đề; nêu ví dụ."},{"ten":"3. Luyện tập","gv":"- GV cho HS làm bài luyện tập tổng hợp (trắc nghiệm + thao tác thực hành).","hs":"- HS làm bài, tự đánh giá và đánh giá bạn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS nhìn lại toàn bộ năng lực số đã hình thành trong năm: dùng thiết bị an toàn, tạo sản phẩm số, tổ chức dữ liệu, ứng xử văn minh trên mạng.\n- (Làm quen AI - mức nhận biết) GV điểm lại: máy tính và công cụ thông minh là trợ thủ giúp con người học tập, làm việc; cần dùng an toàn, trung thực, có trách nhiệm.\n⚠ GV thao tác và kiểm soát hoàn toàn; HS quan sát, không tự nhập thông tin cá nhân; dùng công cụ số trung thực, an toàn.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]},{"lop":3,"mon":"Tin học","tuan":35,"tiet":35,"bai":"Kiểm tra, đánh giá cuối năm học","yccd":"1. Năng lực Tin học (đặc thù):\n- Đánh giá kết quả học tập cả năm: kiến thức và kĩ năng thực hành Tin học lớp 3.\n- Rèn tính trung thực, tự giác, có trách nhiệm khi làm bài và khi sử dụng máy tính.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động quan sát, thao tác, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, hoạt động nhóm hiệu quả.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác hoàn thành hoạt động học tập.\n- Trách nhiệm: giữ trật tự, bảo quản thiết bị, dùng máy tính an toàn, đúng cách.","dodung":"- GV: Phòng máy/máy chiếu, máy tính đã cài phần mềm, bài giảng điện tử, phiếu học tập.\n- HS: SGK Tin học 3 (KNTT), vở ghi; luân phiên thực hành trên máy tính.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV ổn định lớp, phổ biến yêu cầu và hình thức kiểm tra cuối năm.","hs":"- HS lắng nghe, chuẩn bị làm bài."},{"ten":"2. Kiểm tra","gv":"- GV phát đề (trắc nghiệm + thực hành trên máy nếu có phòng máy); theo dõi, hỗ trợ khi cần.","hs":"- HS làm bài kiểm tra một cách trung thực, đúng thời gian."},{"ten":"3. Nhận xét – Đánh giá","gv":"- GV thu bài, nhận xét chung, tuyên dương HS tiến bộ; định hướng học tập tiếp theo.","hs":"- HS lắng nghe nhận xét, tự rút kinh nghiệm."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số) HS thể hiện năng lực số và ý thức sử dụng máy tính an toàn, trung thực trong bài kiểm tra thực hành.\n⚠ Dùng thiết bị, phần mềm an toàn dưới sự hướng dẫn của GV.","hs":"- HS quan sát GV thao tác mẫu; nêu nhận xét, làm theo ở mức đơn giản; có ý thức sử dụng máy tính, Internet an toàn, đúng lứa tuổi."}]}];
